const INTRO_VERSION='brand-particles-v3-local-crest';
const AnimatedPath=Animated.createAnimatedComponent(Path);
const INTRO_PARTICLES=(()=>{
 const anchors=[[55,48],[82,31],[105,26],[128,31],[155,48],[158,86],[158,120],[148,157],[128,188],[105,216],[82,188],[62,157],[52,120],[52,86],[55,48]];
 const pts=[];
 for(let s=0;s<anchors.length-1;s++){
  const a=anchors[s],b=anchors[s+1],steps=4;
  for(let j=0;j<steps;j++){
   const t=j/steps;
   pts.push({x:a[0]+(b[0]-a[0])*t,y:a[1]+(b[1]-a[1])*t});
  }
 }
 return pts.map((p,i)=>{
  const angle=(i*137.508)*Math.PI/180;
  const radius=18+(i%7)*4.5;
  return {...p,dx:Math.cos(angle)*radius,dy:Math.sin(angle)*radius,delay:(i%11)*.018+Math.floor(i/11)*.01,size:2.2+(i%4)*.65};
 });
})();
const fs=n=>{
 let v=n;
 if(Platform.OS!=='web'){
  if(n<6)v=n*1.75;
  else if(n<10)v=n*1.60;
  else if(n<15)v=n*1.30;
 }
 return Math.round((v+1)*10)/10;
};
const FOLLOWABLE_SPORTS=['FUTEBOL','FUTEBOL FEMININO','FUTSAL MASCULINO','FUTSAL FEMININO','FORMAÇÃO'];
const sportLabel=v=>({
 'FUTEBOL':'Futebol Masculino',
 'FUTEBOL FEMININO':'Futebol Feminino',
 'FUTSAL MASCULINO':'Futsal Masculino',
 'FUTSAL FEMININO':'Futsal Feminino',
 'FORMAÇÃO':'Formação'
}[v]||v);
function teamSportKey(team){
 const sport=String(team?.sports?.name||'').toUpperCase();
 const gender=String(team?.gender||'').toUpperCase();
 const age=String(team?.age_group||'').toUpperCase();
 if(age&&age!=='SENIORES'&&age!=='SENIOR')return 'FORMAÇÃO';
 const female=gender==='F'||/FEM|FEMALE|WOMEN|MULHER/.test(gender);
 if(/FUTSAL/.test(sport))return female?'FUTSAL FEMININO':'FUTSAL MASCULINO';
 if(/FUTEBOL|FOOTBALL|SOCCER/.test(sport))return female?'FUTEBOL FEMININO':'FUTEBOL';
 return null;
}
function newsSportKey(item){
 const category=String(item?.category||'').toUpperCase();
 const text=(category+' '+String(item?.title||'')).normalize('NFD').replace(/[\u0300-\u036f]/g,'');
 if(/FUTSAL/.test(text))return /FEMIN|WOMEN|FEM/.test(text)?'FUTSAL FEMININO':'FUTSAL MASCULINO';
 if(/FUTEBOL FEMININO|LIGA BPI|WOMEN/.test(text))return 'FUTEBOL FEMININO';
 if(/FORMACAO|SUB[- ]?\d|JUNIOR|JUVENIL/.test(text))return 'FORMAÇÃO';
 if(/^FUTEBOL$/.test(category.normalize('NFD').replace(/[\u0300-\u036f]/g,'')))return 'FUTEBOL';
 return null;
}
const SUPABASE_URL='https://vcvnmcewoocoizjljmbc.supabase.co';
const SUPABASE_KEY='sb_publishable_TyM24TpRzq3_ijZsFRTVGg_bWM2WOky';
const SB_HEADERS={apikey:SUPABASE_KEY,Authorization:'Bearer '+SUPABASE_KEY,'Cache-Control':'no-cache','Pragma':'no-cache'};
async function sb(path){
 const r=await fetch(SUPABASE_URL+'/rest/v1/'+path,{headers:SB_HEADERS,cache:'no-store'});
 if(!r.ok)throw new Error('Supabase '+r.status);
 return r.json();
}
async function edge(name,options={}){
 const r=await fetch(SUPABASE_URL+'/functions/v1/'+name,{
  ...options,
  headers:{apikey:SUPABASE_KEY,Authorization:'Bearer '+SUPABASE_KEY,'Content-Type':'application/json',...(options.headers||{})}
 });
 const data=await r.json().catch(()=>({}));
 if(!r.ok){const e=new Error(data?.error||'Erro no serviço.');e.data=data;throw e}
 return data;
}

function RemoteLogo({uri,style,alt,onError}) {
 if(!uri)return null;
 const nativeUri=Platform.OS!=='web'&&uri===LOGO_URL?LOGO_NATIVE_URL:uri;
 return Platform.OS==='web'
  ?React.createElement('img',{src:nativeUri,style:{...style,objectFit:'contain'},alt,onError})
  :<Image source={{uri:nativeUri}} style={style} resizeMode="contain" onError={onError}/>;
}
function TeamLogo({name,uri,style}){
 const [failed,setFailed]=useState(false);
 useEffect(()=>setFailed(false),[uri,name]);
 const isTorreense=/^SCU Torreense/i.test(name||'');
 const finalUri=uri||(isTorreense?(Platform.OS==='web'?LOGO_URL:LOGO_NATIVE_URL):null);
 if(finalUri&&!failed)return <RemoteLogo uri={finalUri} style={style} alt={name||'Equipa'} onError={()=>setFailed(true)}/>;
 const initials=(name||'?').split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase();
 return <View style={[style,s.teamLogoFallback]}><Text style={s.teamLogoFallbackText}>{initials}</Text></View>;
}
function PlayerPhoto({player,compact=false,detail=false,teamName='SCU Torreense',teamLogo=null}){
 const [failed,setFailed]=useState(false);
 useEffect(()=>setFailed(false),[player?.photo_url,player?.id,teamName,teamLogo]);
 const style=detail?s.playerPhotoDetail:compact?s.playerPhotoCompact:s.playerPhoto;
 if(player?.photo_url&&!failed)return <Image source={{uri:player.photo_url}} style={style} resizeMode={detail?'contain':'cover'} onError={()=>setFailed(true)}/>;
 return <View style={[style,s.playerPhotoFallback]}><TeamLogo name={teamName} uri={teamLogo} style={detail?s.playerPhotoLogo:s.playerPhotoLogoCompact}/></View>;
}
function YouTubeBadge({onPress,summary=false,label='Abrir vídeo no YouTube'}){
 return <Pressable accessibilityRole="button" accessibilityLabel={label} hitSlop={7} onPress={e=>{e?.stopPropagation?.();onPress?.()}} style={s.youtubeBadge}>
  <View style={s.youtubeIcon}><Text style={s.youtubePlay}>▶</Text>{summary?<View style={s.youtubeSummaryMark}><Text style={s.youtubeSummaryMarkText}>R</Text></View>:null}</View>
 </Pressable>;
}
