const LIGHT_DARK_TEXT=new Set([
 'scutvTitle','memberMessage','benefitMiniTitle','benefitSearch','newsHeading','newsListHeading',
 'calendarSectionTitle','classificationCompetitionTitle','playerDetailSectionTitle','playerDetailName','gamesMonthTitle','homeSectionTitle'
]);
const LIGHT_ACCENT_TEXT=new Set([
 'calendarTopTabTextOn','playerDetailTabTextOn'
]);
const LIGHT_PRIMARY_BG=new Set([
 'hubPrimaryButton','loginButton','memberSubmit','storeAdd','productAdd','checkoutBtn'
]);
const LIGHT_PRIMARY_TEXT=new Set([
 'hubPrimaryButtonText','loginButtonText','memberSubmitText','storeAddText','productAddText','checkoutText'
]);
const LIGHT_SELECTED_BG=new Set([
 'profileSportCheckOn','notifySwitchOn','memberPaymentOptionOn','memberCheckOn','benefitDiscountCompact',
 'benefitDiscount','cartBadge','playerNumberBadge'
]);
const LIGHT_SELECTED_TEXT=new Set([
 'profileSportCheckText','memberPaymentOptionTextOn','memberCheckMark','benefitDiscountCompactText',
 'benefitDiscountText','cartBadgeText','playerNumber'
]);

function lightThemeStyle(name,base){
 const flat=StyleSheet.flatten(base);
 if(!flat)return base;
 const out={...flat};
 const mapText=v=>{
  const x=String(v||'').toLowerCase();
  if(['#17324a','#082b48','#17212a','#111','#111111'].includes(x))return '#25282d';
  if(['#667b8c','#8797a4','#60788a','#6f7880','#7e8790','#4b545b'].includes(x))return '#6f747a';
  if(x==='#f1b94f'||x==='#a91f42')return '#8f173b';
  return v;
 };
 const mapBorder=v=>{
  const x=String(v||'').toLowerCase();
  if(['#d7e0e7','#dce4ea','#e5ebf0','#e8edf0','#e9eef2','#e4e9ed','#edf1f4','#b6c3cc','#bdcbd5'].includes(x))return '#e3e3e6';
  if(x==='#f1b94f'||x==='#a91f42'||x.includes('241,185,79'))return '#cdaab6';
  if(x.includes('120,164,197')||x.includes('165,205,229'))return '#dedee2';
  if(x.includes('255,255,255'))return '#e6e6e8';
  return v;
 };
 const mapBg=v=>{
  const x=String(v||'').toLowerCase();
  if(['#f3f6f8','#f8fafb','#f9fafb','#eef3f6','#f4f4f4'].includes(x))return '#f5f5f6';
  if(x==='#f1b94f'||x.includes('241,185,79'))return '#f8eef1';
  if(/^rgba\(255,255,255,\.0/.test(x))return '#f5f5f6';
  return v;
 };
 if(out.color)out.color=mapText(out.color);
 if(out.backgroundColor)out.backgroundColor=mapBg(out.backgroundColor);
 if(out.borderColor)out.borderColor=mapBorder(out.borderColor);
 if(out.borderTopColor)out.borderTopColor=mapBorder(out.borderTopColor);
 if(out.borderBottomColor)out.borderBottomColor=mapBorder(out.borderBottomColor);
 if(out.borderLeftColor)out.borderLeftColor=mapBorder(out.borderLeftColor);
 if(out.borderRightColor)out.borderRightColor=mapBorder(out.borderRightColor);

 if(LIGHT_DARK_TEXT.has(name))out.color='#25282d';
 if(LIGHT_ACCENT_TEXT.has(name))out.color='#8f173b';

 // In Light theme, every unselected navigation/filter label must stay readable.
 if(['filterText','calendarTopTabText','classificationCompetitionChipText','classificationFilterLabel','playerDetailTabText'].includes(name))out.color='#34383d';
 if(name==='filter'){out.backgroundColor='#ffffff';out.borderColor='#d6d9dd'}
 if(name==='classificationCompetitionChip'){out.backgroundColor='#ffffff';out.borderColor='#d6d9dd'}
 if(name==='calendarTabs'){out.borderBottomColor='#d9dde1'}
 if(name==='bottomNav'){out.backgroundColor='rgba(255,255,255,.98)';out.borderColor='#dde0e4'}
 if(name==='bottomNavText')out.color='#59626b';
 if(['calendarViewButtonText','monthCalendarTitle','monthDayNumber','monthSelectedTitle'].includes(name))out.color='#34383d';
 if(name==='calendarViewButton'){out.backgroundColor='transparent'}
 if(name==='calendarViewToggle'){out.backgroundColor='#e9eaed'}
 if(name==='calendarViewButtonOn'){out.backgroundColor='#8f173b'}
 if(name==='calendarViewButtonTextOn')out.color='#ffffff';
 if(name==='homeMatchHero'){out.backgroundColor='#11182d';out.borderColor='rgba(17,24,45,.18)'}
 if(['homeMatchTeamName','homeMatchCountdown','homeMatchVs','homeMatchTicketText','homeMatchGameText'].includes(name))out.color='#ffffff';
 if(['homeMatchDate','homeMatchMeta','homeMatchCalendarLink','homeMatchCountdownLabel'].includes(name))out.color='#b7c0cf';
 if(name==='homeMatchCompetition'){out.backgroundColor='#5f718c';out.color='#ffffff'}
 if(name==='homeMatchGame'){out.backgroundColor='rgba(255,255,255,.03)';out.borderColor='#ffffff'}
 if(name==='homeMatchGameText')out.color='#ffffff';
 if(name==='homeMatchTicket'){out.backgroundColor='#8f173b';out.borderColor='#8f173b'}
 if(name==='homeMatchTicketText')out.color='#ffffff';
 if(name==='calendarTopTabText')out.color='#34383d';
 if(name==='calendarTopTabTextOn'){out.color='#8f173b';out.fontWeight='900'}


 if(LIGHT_PRIMARY_BG.has(name)){out.backgroundColor='#8f173b';out.borderColor='#8f173b'}
 if(LIGHT_PRIMARY_TEXT.has(name))out.color='#ffffff';
 if(LIGHT_SELECTED_BG.has(name)){out.backgroundColor='#8f173b';out.borderColor='#8f173b'}
 if(LIGHT_SELECTED_TEXT.has(name))out.color='#ffffff';

 // Selected chips/tabs stay light, using burgundy only for emphasis.
 if(['filterOn','gameTabOn','optionChipOn','deliveryChoiceOn'].includes(name)){
  out.backgroundColor='#fbf3f6';out.borderColor='#cdaab6';
 }
 if(['filterTextOn','gameTabTextOn','optionChipTextOn','deliveryChoiceTextOn','calendarTopTabTextOn'].includes(name))out.color='#8f173b';
 if(name==='calendarTopTabOn')out.borderBottomColor='#8f173b';

 // Form fields become neutral white/light-gray with dark text.
 if(['loginInput','memberInput','checkoutInput','benefitSearch'].includes(name)){
  out.backgroundColor='#ffffff';out.borderColor='#dddddf';out.color='#25282d';
 }
 return out;
}

const s=new Proxy(_baseStyles,{
 get(target,prop){
  const base=target[prop];
  return lightThemeStyle(String(prop),base);
 }
});